def evaluate_current_investigation(
    state: dict[str, Any],
) -> dict[str, Any]:
    """
    Evaluate whether the investigation should continue.
    """

    from app.agent.evaluator import (
        COMPLETE,
        evaluate_investigation,
    )

    evaluation = evaluate_investigation(
        intent=state.get(
            "intent",
            "general_search",
        ),
        evidence=state.get(
            "evidence",
            [],
        ),
        executed_tools=state.get(
            "executed_tools",
            [],
        ),
        current_step=state.get(
            "current_step",
            0,
        ),
        max_steps=state.get(
            "max_steps",
            0,
        ),
    )

    state["investigation_decision"] = (
        evaluation.decision
    )

    state["investigation_reason"] = (
        evaluation.reason
    )

    if evaluation.decision == COMPLETE:

        state["needs_more_investigation"] = False
        state["investigation_complete"] = True

    else:

        state["needs_more_investigation"] = True
        state["investigation_complete"] = False

    return state

def should_continue(
    state: InvestigationState,
) -> str:
    """
    Decide whether another investigation tool should run.
    """

    if state.get(
        "needs_more_investigation",
        False,
    ):
        return "execute_tool"

    return "next"

def create_plan(
    state: dict[str, Any],
) -> dict[str, Any]:
    """
    Create a deterministic investigation plan.
    """

    try:

        plan = build_investigation_plan(
            intent=state.get(
                "intent",
                "general_search",
            ),
            identifiers=state.get(
                "identifiers",
                [],
            ),
            keywords=state.get(
                "keywords",
                [],
            ),
        )

        state["investigation_plan"] = [
            step.tool_name
            for step in plan.steps
        ]

        state["plan_reasons"] = {
            step.tool_name: step.reason
            for step in plan.steps
        }

        state["max_steps"] = plan.max_steps

        state["current_step"] = 0

        state["needs_more_investigation"] = bool(
            plan.steps
        )

    except Exception as exc:

        error = (
            f"Investigation planning failed: {exc}"
        )

        state["errors"] = (
            state.get("errors", [])
            + [error]
        )

        state["investigation_plan"] = [
            "repository_search"
        ]

        state["plan_reasons"] = {
            "repository_search": (
                "Fallback repository search."
            )
        }

        state["max_steps"] = 1
        state["current_step"] = 0

        state["needs_more_investigation"] = True

    return state

class MCPAgentTools:
    """
    Adapter between the LangGraph agent and MCP tools.
    """

    def __init__(
        self,
        registry: MCPToolRegistry | None = None,
    ) -> None:
        self.registry = (
            registry
            if registry is not None
            else MCPToolRegistry(
                local_copilot_server_config()
            )
        )

    async def discover_tools(
        self,
    ) -> list[MCPToolDefinition]:
        """
        Discover MCP tools available to the agent.
        """

        return await self.registry.discover()

    def list_tools(
        self,
    ) -> list[MCPToolDefinition]:
        """
        Return currently discovered tools.
        """

        return self.registry.list_tools()

    async def execute(
        self,
        tool_name: str,
        arguments: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """
        Execute an MCP tool and normalize its result.
        """

        result = await self.registry.execute(
            tool_name,
            arguments,
        )

        return normalize_mcp_result(
            result
        )

    def list_traces(
        self,
    ) -> list[MCPTrace]:
        """
        Return MCP execution traces.
        """

        return self.registry.client.tracer.list_traces()

    def trace_snapshot(
        self,
    ) -> list[dict[str, Any]]:
        """
        Return serializable MCP traces.
        """

        return self.registry.client.tracer.snapshot()

    def clear_traces(self) -> None:
        """
        Clear retained MCP traces.
        """

        self.registry.client.tracer.clear()

def index_mcp_tools(
    tools: list[MCPToolDefinition],
) -> dict[str, MCPToolDefinition]:
    """
    Build a runtime catalog from discovered MCP tools.
    """

    return {
        tool.name: tool
        for tool in tools
    }

def from_mcp_tool(
    cls,
    tool: Any,
    *,
    server_name: str,
) -> "MCPToolDefinition":
    return cls(
        name=tool.name,
        description=tool.description or "",
        input_schema=dict(tool.inputSchema),
        server_name=server_name,
        title=getattr(tool, "title", None),
    )

def should_retry(
    error: Any,
    *,
    attempt: int,
    config: RetryConfig,
) -> RetryDecision:
    """
    Determine whether another attempt is allowed.
    """

    if attempt >= config.max_attempts:
        return RetryDecision(
            retry=False,
            reason="Maximum MCP retry attempts reached.",
        )

    return classify_error(error)

def classify_error(
    error: Any,
) -> RetryDecision:
    """
    Determine whether an error looks transient.

    This intentionally uses conservative matching:
    unknown tools, validation errors, and permission failures
    should not be retried.
    """

    message = str(error).lower()

    for keyword in NON_RETRYABLE_ERROR_KEYWORDS:
        if keyword in message:
            return RetryDecision(
                retry=False,
                reason=(
                    f"Non-retryable MCP error: "
                    f"{keyword}"
                ),
            )

    for keyword in TRANSIENT_ERROR_KEYWORDS:
        if keyword in message:
            return RetryDecision(
                retry=True,
                reason=(
                    f"Transient MCP error: "
                    f"{keyword}"
                ),
            )

    return RetryDecision(
        retry=False,
        reason="MCP error is not classified as transient.",
    )

class DynamicMCPTools:
    """
    Bridge between LangGraph and dynamically discovered MCP tools.

    The registry owns tool discovery and caching.
    The adapter provides the interface used by the agent.
    """

    def __init__(
        self,
        registry: MCPToolRegistry | None = None,
    ) -> None:
        self.registry = (
            registry
            if registry is not None
            else MCPToolRegistry(
                local_copilot_server_config()
            )
        )

    async def discover(
        self,
        *,
        force_refresh: bool = False,
    ) -> list[MCPToolDefinition]:
        """
        Discover MCP tools.

        Results are cached by the registry unless
        force_refresh=True.
        """

        return await self.registry.discover(
            force_refresh=force_refresh,
        )

    async def execute(
    self,
    tool_name: str,
    arguments: dict[str, Any],
) -> dict[str, Any]:
        """
        Execute an MCP tool and normalize the result.

        Preserve structured_content returned by the MCP registry.
        """

        result = await self.registry.execute(
            tool_name,
            arguments,
        )

        normalized = normalize_mcp_result(result)

        if (
            normalized.get("structured_content") is None
            and isinstance(result, dict)
            and "structured_content" in result
        ):
            normalized["structured_content"] = result.get(
                "structured_content"
            )

        return normalized

    def has_tool(
        self,
        tool_name: str,
    ) -> bool:
        """
        Check whether a tool is currently available
        in the cached catalog.
        """

        return self.registry.has_tool(
            tool_name
        )

    def get_tool(
        self,
        tool_name: str,
    ) -> MCPToolDefinition | None:
        """
        Return a cached tool definition.
        """

        return self.registry.get(
            tool_name
        )

    def list_tools(
        self,
    ) -> list[MCPToolDefinition]:
        """
        Return all currently cached MCP tools.
        """

        return self.registry.list_tools()

class PatchValidator:
    """
    Validates generated code changes without
    modifying the repository.
    """

    def __init__(
        self,
        repository_root: Path,
    ) -> None:
        self.repository_root = (
            repository_root.resolve()
        )

    def validate(
        self,
        proposal: ChangeProposal,
    ) -> ValidationResult:
        issues: list[
            ValidationIssue
        ] = []

        checked_files: list[str] = []

        issues.extend(
            validate_proposal_paths(
                proposal,
                self.repository_root,
            )
        )

        issues.extend(
            validate_proposal_changes(
                proposal
            )
        )

        for change in proposal.changes:
            if not change.is_modified:
                continue

            checked_files.append(
                change.path
            )

            if change.path.lower().endswith(
                ".py"
            ):
                issues.extend(
                    self._validate_python_file(
                        change.path,
                        change.proposed_content,
                    )
                )

        discovered_tests = (
            discover_tests(
                self.repository_root
            )
        )

        if not discovered_tests:
            issues.append(
                ValidationIssue(
                    severity=(
                        ValidationSeverity.WARNING
                    ),
                    code="NO_TESTS_FOUND",
                    message=(
                        "No test files were "
                        "discovered."
                    ),
                )
            )

        valid = not any(
            issue.severity
            == ValidationSeverity.ERROR
            for issue in issues
        )

        return ValidationResult(
            valid=valid,
            issues=issues,
            checked_files=checked_files,
            discovered_tests=(
                discovered_tests
            ),
        )

    def _validate_python_file(
        self,
        path: str,
        content: str,
    ) -> list[ValidationIssue]:
        issues: list[
            ValidationIssue
        ] = []

        syntax_issues = (
            validate_python_syntax(
                content,
                path=path,
            )
        )

        for (
            code,
            message,
            line,
        ) in syntax_issues:
            issues.append(
                ValidationIssue(
                    severity=(
                        ValidationSeverity.ERROR
                    ),
                    code=code,
                    message=message,
                    path=path,
                    line=line,
                )
            )

        # AST validation is only meaningful
        # if syntax parsing succeeded.
        if not syntax_issues:
            ast_issues = (
                validate_python_ast(
                    content,
                    path=path,
                )
            )

            for (
                code,
                message,
                line,
            ) in ast_issues:
                issues.append(
                    ValidationIssue(
                        severity=(
                            ValidationSeverity.ERROR
                        ),
                        code=code,
                        message=message,
                        path=path,
                        line=line,
                    )
                )

        return issues

    def validate_patch(
    self,
    proposal: ChangeProposal,
):
        """
        Run the complete Phase 4.3 validation pipeline.
        """

        validator = PatchValidator(
            self.repository_root
        )

        result = validator.validate(
            proposal
        )

        proposal.validation_errors.clear()
        proposal.validation_warnings.clear()

        for issue in result.issues:
            if (
                issue.severity.value
                == "error"
            ):
                proposal.validation_errors.append(
                    issue.message
                )

            elif (
                issue.severity.value
                == "warning"
            ):
                proposal.validation_warnings.append(
                    issue.message
                )

        if result.valid:
            proposal.status = (
                ChangeStatus.VALIDATED
            )
        else:
            proposal.status = (
                ChangeStatus.FAILED
            )

        return result

def prepare(
    self,
    proposal: ChangeProposal,
) -> ApprovalRequest:
    """
    Validate a proposal and prepare the
    information required for human review.

    No repository files are modified.
    """

    validation = (
        self.change_manager.validate_patch(
            proposal
        )
    )

    if not validation.valid:
        raise ApprovalError(
            "Patch failed validation and "
            "cannot be submitted for approval."
        )

    diff = self.change_manager.diff(
        proposal
    )

    return build_approval_request(
        proposal,
        diff=diff,
        validation=validation,
    )

