class ApplyAndVerify:
    """
    Coordinates:

        approved proposal
            ↓
        safe application
            ↓
        automated verification
            ↓
        rollback on failure
    """

    def __init__(
        self,
        repository_root: Path,
        test_timeout_seconds: float = 300.0,
    ) -> None:
        self.repository_root = (
            repository_root.resolve()
        )

        self.applier = SafePatchApplier(
            self.repository_root
        )

        self.verifier = ChangeVerifier(
            self.repository_root,
            timeout_seconds=(
                test_timeout_seconds
            ),
        )

    def execute(
        self,
        proposal: ChangeProposal,
    ) -> VerificationResult:
        """
        Apply and verify an approved proposal.

        If verification fails, automatically roll
        the repository back to its pre-change state.
        """

        try:
            self.applier.apply(
                proposal
            )

        except PatchApplicationError:
            raise

        verification = (
            self.verifier.verify(
                proposal
            )
        )

        if verification.passed:
            return verification

        rollback_error: str | None = None

        try:
            self.applier.rollback(
                proposal
            )

            verification.rollback_performed = (
                True
            )

        except Exception as exc:
            rollback_error = str(exc)

            verification.rollback_error = (
                rollback_error
            )

            raise PostChangeVerificationError(
                "Post-change verification failed "
                "and repository rollback failed."
            ) from exc

        return verification

    def apply(
    self,
    proposal: ChangeProposal,
) -> ChangeProposal:
        """
        Apply an approved proposal safely.
        """

        applier = SafePatchApplier(
            self.repository_root
        )

        return applier.apply(
            proposal
        )

def __init__(
    self,
    repository_root: Path,
    test_timeout_seconds: float = 300.0,
) -> None:
    self.repository_root = (
        repository_root.resolve()
    )

    self.applier = SafePatchApplier(
        self.repository_root
    )

    self.verifier = ChangeVerifier(
        self.repository_root,
        timeout_seconds=(
            test_timeout_seconds
        ),
    )

def _validate_proposal(
    self,
    proposal: ChangeProposal,
) -> list[Path]:
    if proposal.status != (
        ChangeStatus.APPROVED
    ):
        raise PatchApplicationError(
            "Only APPROVED proposals can be applied."
        )

    if proposal.is_empty:
        raise PatchApplicationError(
            "Cannot apply an empty proposal."
        )

    validated_paths: list[Path] = []

    for change in proposal.changes:
        try:
            path = validate_change_path(
                self.repository_root,
                change.path,
            )
        except ChangeSafetyError as exc:
            raise PatchApplicationError(
                str(exc)
            ) from exc

        validated_paths.append(path)

    return validated_paths

def execute(
    self,
    proposal: ChangeProposal,
) -> VerificationResult:
    """
    Apply and verify an approved proposal.

    If verification fails, automatically roll
    the repository back to its pre-change state.
    """

    try:
        self.applier.apply(
            proposal
        )

    except PatchApplicationError:
        raise

    verification = (
        self.verifier.verify(
            proposal
        )
    )

    if verification.passed:
        return verification

    rollback_error: str | None = None

    try:
        self.applier.rollback(
            proposal
        )

        verification.rollback_performed = (
            True
        )

    except Exception as exc:
        rollback_error = str(exc)

        verification.rollback_error = (
            rollback_error
        )

        raise PostChangeVerificationError(
            "Post-change verification failed "
            "and repository rollback failed."
        ) from exc

    return verification

def _build_investigation(
    result: VerificationResult,
    likely_files: list[str],
) -> str:
    if result.status == VerificationStatus.TIMED_OUT:
        return (
            "Investigate the test execution timeout and determine "
            "whether the change introduced an execution or performance issue."
        )

    if result.status == VerificationStatus.ERROR:
        return (
            "Investigate the test runner error before generating "
            "another code change."
        )

    if likely_files:
        files = ", ".join(likely_files[:10])

        return (
            "Investigate the failing test output and the affected "
            f"repository files: {files}."
        )

    return (
        "Investigate the failing test output and identify the "
        "repository code responsible for the failure."
    )

