def extract_definition_targets(query: str) -> list[str]:
    targets: list[str] = []

    # Explicit code-like identifiers are strong targets.
    targets.extend(extract_identifiers(query))

    match = DEFINITION_QUERY_PATTERN.search(query)

    if match:
        phrase = _normalise_definition_phrase(match.group(1))

        if phrase:
            targets.append(phrase)

            words = [
                word
                for word in phrase.split()
                if word.lower() not in DEFINITION_STOP_WORDS
            ]

            # Only add a single-word target when the original
            # phrase itself contains one meaningful word.
            #
            # Avoid turning phrases such as:
            #   "autonomous failure investigation"
            #   "repository-aware code search"
            # into generic targets like "investigation" or "search".
            if len(words) == 1:
                targets.append(words[0])

    match = SIMPLE_DEFINITION_PATTERN.search(query)

    if match:
        target = _clean_identifier(match.group(1))

        if target:
            targets.append(target)

    return list(dict.fromkeys(
        target
        for target in targets
        if target
    ))

